 public Vector3 DockPointerPoint{get;private set;}
 public bool UseDesktopCursor=true;
 public bool DockHovered{get;private set;}public float DockOpacity=>dockFade!=null?dockFade.alpha:0;
 public readonly Collider[] CategoryButtons=new Collider[5];public readonly Collider[] UtilityButtons=new Collider[3];
 Collider dockRail,toolRail;GameObject dockRow;CanvasGroup dockFade;UnityEngine.UI.Text dockTooltip;Material dockDisk,dockInk;
 readonly UnityEngine.UI.Image[] categoryImages=new UnityEngine.UI.Image[5];readonly UnityEngine.UI.Text[] toolLabels=new UnityEngine.UI.Text[ToolCount];
 Vector3 dockEyeAt;bool dockPressedLast,dockPosed;float dockIdle,followDwell;Action showBook,showMenu;
 public static GodToolCategory CategoryFor(SpiritualTool kind){switch(kind){case SpiritualTool.RaiseGround:case SpiritualTool.LowerGround:case SpiritualTool.SmoothGround:return GodToolCategory.Terraform;case SpiritualTool.Rain:case SpiritualTool.RainBrush:case SpiritualTool.WindFan:case SpiritualTool.Lightning:case SpiritualTool.Whirlwind:return GodToolCategory.Weather;case SpiritualTool.Heal:case SpiritualTool.PlantSeeds:return GodToolCategory.Life;case SpiritualTool.FoodGift:case SpiritualTool.WoodGift:return GodToolCategory.Offerings;default:return GodToolCategory.Guidance;}}
 public void BindDock(Action book,Action menu){showBook=book;showMenu=menu;}
 public void HideDock(){if(view!=null)view.SetActive(false);DockHovered=false;dockPosed=false;}
 void BuildDock(){
  dockDisk=new Material(Resources.Load<Shader>("GodToolIcons/DockDisk")){name="Private circular stone dock disks"};dockInk=new Material(Resources.Load<Shader>("Book/CreationBookUI")){name="Private dock labels and sourced glyphs"};
  view=new GameObject("God tools field-of-view dock",typeof(UnityEngine.Canvas),typeof(CanvasGroup));view.transform.SetParent(transform,false);view.GetComponent<UnityEngine.Canvas>().renderMode=RenderMode.WorldSpace;view.GetComponent<RectTransform>().sizeDelta=new Vector2(980,300);dockFade=view.GetComponent<CanvasGroup>();dockFade.alpha=.28f;
  var basePlate=Panel("Quiet rounded dock rail",view.transform,new Vector2(980,140),new Vector2(0,-20),Color.white);basePlate.material=buttonStone;basePlate.raycastTarget=false;basePlate.gameObject.layer=2;dockRail=basePlate.gameObject.AddComponent<BoxCollider>();dockRail.isTrigger=true;((BoxCollider)dockRail).size=new Vector3(980,140,2);((BoxCollider)dockRail).center=Vector3.forward*20;
  var representative=new[]{SpiritualTool.RaiseGround,SpiritualTool.Rain,SpiritualTool.PlantSeeds,SpiritualTool.FoodGift,SpiritualTool.Help};
  for(int i=0;i<5;i++){var category=(GodToolCategory)i;var b=DockButton(category.ToString(),view.transform,new Vector2((i-2)*112,0),true);CategoryButtons[i]=b.GetComponent<Collider>();categoryImages[i]=b;DockGlyph(representative[i],b.transform);DockText("Category",b.transform,new Vector2(0,-48),new Vector2(108,22),14).text=category.ToString();}
  var empty=DockButton("Empty hand",view.transform,new Vector2(-350,0),false);UtilityButtons[0]=empty.GetComponent<Collider>();choices[ToolCount+1]=UtilityButtons[0];DockGlyph(SpiritualTool.Help,empty.transform);
  var book=DockButton("Book of Creation",view.transform,new Vector2(350,0),false);UtilityButtons[1]=book.GetComponent<Collider>();DockBookGlyph(book.transform,13);
  var menu=DockButton("Sanctuary menu",view.transform,new Vector2(440,0),false);UtilityButtons[2]=menu.GetComponent<Collider>();DockBookGlyph(menu.transform,7);
  dockRow=new GameObject("Expanded category tools",typeof(RectTransform));dockRow.transform.SetParent(view.transform,false);var tray=Panel("Rounded category tray",dockRow.transform,new Vector2(650,118),new Vector2(0,120),Color.white);tray.material=buttonStone;tray.raycastTarget=false;tray.gameObject.layer=2;toolRail=tray.gameObject.AddComponent<BoxCollider>();toolRail.isTrigger=true;((BoxCollider)toolRail).size=new Vector3(650,118,2);((BoxCollider)toolRail).center=Vector3.forward*20;
  for(int i=0;i<ToolCount;i++){var b=DockButton(Title(ToolKinds[i]),dockRow.transform,Vector2.zero,true);choices[i]=b.GetComponent<Collider>();DockGlyph(ToolKinds[i],b.transform);toolLabels[i]=DockText("Tool name",b.transform,new Vector2(0,-46),new Vector2(130,24),14);toolLabels[i].text=Title(ToolKinds[i]);toolLabels[i].gameObject.SetActive(false);}
  var clear=DockButton("Clear guidance cue",dockRow.transform,new Vector2(275,120),false);choices[ToolCount]=clear.GetComponent<Collider>();DockBookGlyph(clear.transform,12);DockText("Clear cue label",clear.transform,new Vector2(0,-46),new Vector2(105,22),13).text="Clear cue";
  dockTooltip=DockText("Hovered dock item",view.transform,new Vector2(0,190),new Vector2(620,27),18);
  var credit=DockText("Open icon attribution",dockRow.transform,new Vector2(0,218),new Vector2(800,18),9);credit.text=GodToolEmblems.Credit+" · Utility icons: Lucide (ISC)";
  energy=DockText("Spiritual energy",view.transform,new Vector2(345,-69),new Vector2(180,20),12);
  energyFill=Panel("Energy remaining",view.transform,new Vector2(68,3),new Vector2(390,-85),new Color(.6f,.85f,.72f));energyFill.material=dockInk;
  hint=DockText("Selected tool use",view.transform,new Vector2(-80,-73),new Vector2(640,26),14);hint.gameObject.SetActive(false);RefreshDockRows();
 }
 UnityEngine.UI.Image DockButton(string name,Transform parent,Vector2 at,bool circular){var b=Panel(name,parent,new Vector2(80,80),at,Color.white);b.material=circular?dockDisk:buttonStone;b.raycastTarget=false;b.gameObject.layer=2;var hit=b.gameObject.AddComponent<BoxCollider>();hit.isTrigger=true;hit.center=Vector3.back*4;hit.size=new Vector3(80,80,12);return b;}
 UnityEngine.UI.Text DockText(string name,Transform parent,Vector2 at,Vector2 size,int pixels){var label=Text(name,parent,at,size,pixels);label.material=dockInk;label.color=new Color(.98f,.94f,.8f);return label;}
 void DockGlyph(SpiritualTool kind,Transform parent){int index=kind==SpiritualTool.Lightning?3:TerrainSculptor.IsSculpt(kind)?7:kind==SpiritualTool.Whirlwind?6:(int)kind;var g=new GameObject("Sourced tool glyph",typeof(RectTransform),typeof(UnityEngine.UI.RawImage));g.transform.SetParent(parent,false);var icon=g.GetComponent<UnityEngine.UI.RawImage>();icon.material=dockInk;icon.raycastTarget=false;icon.color=new Color(.98f,.94f,.8f);icon.texture=Resources.Load<Texture2D>(kind==SpiritualTool.Lightning?"GodToolIcons/lightning":TerrainSculptor.IsSculpt(kind)?"GodToolIcons/terrain":"GodToolIcons/atlas");icon.uvRect=kind==SpiritualTool.Lightning||TerrainSculptor.IsSculpt(kind)?new Rect(0,0,1,1):new Rect((index%5)*.2f,.5f-(index/5)*.5f,.2f,.5f);icon.rectTransform.sizeDelta=new Vector2(48,48);if(kind==SpiritualTool.LowerGround)g.transform.localRotation=Quaternion.Euler(0,0,180);if(kind==SpiritualTool.SmoothGround)g.transform.localScale=new Vector3(1,.45f,1);}
 void DockBookGlyph(Transform parent,int index){var g=new GameObject("Sourced utility glyph",typeof(RectTransform),typeof(UnityEngine.UI.RawImage));g.transform.SetParent(parent,false);var icon=g.GetComponent<UnityEngine.UI.RawImage>();icon.material=dockInk;icon.texture=Resources.Load<Texture2D>("BookIcons/atlas");icon.uvRect=new Rect(index%4*.25f,1-(index/4+1)*.25f,.25f,.25f);icon.rectTransform.sizeDelta=new Vector2(44,44);icon.color=new Color(.98f,.94f,.8f);icon.raycastTarget=false;}
 public void OpenCategory(GodToolCategory category){if(!Enum.IsDefined(typeof(GodToolCategory),category)||Season.paused||miracles.Suspended)return;CancelSculpt();Brush.Stop();SeedVisibility(false);preview.SetActive(false);hint.gameObject.SetActive(false);ActiveCategory=category;Open=true;releaseGate=true;dockIdle=0;view.SetActive(true);RefreshDockRows();}
 void RefreshDockRows(){if(dockRow==null)return;dockRow.SetActive(Open);int count=0;foreach(var kind in ToolKinds)if(CategoryFor(kind)==ActiveCategory)count++;int column=0;for(int i=0;i<ToolCount;i++){bool visible=Open&&CategoryFor(ToolKinds[i])==ActiveCategory;choices[i].gameObject.SetActive(visible);if(visible)choices[i].GetComponent<RectTransform>().anchoredPosition=new Vector2((column++-(count-1)*.5f)*112,120);}choices[ToolCount].gameObject.SetActive(Open&&ActiveCategory==GodToolCategory.Guidance);}
 void PoseDock(float dt,bool xr){var e=eye.transform.eulerAngles;var facing=Quaternion.Euler(xr?Mathf.Clamp(Mathf.DeltaAngle(0,e.x),-30,30):Mathf.DeltaAngle(0,e.x),e.y,0);var position=eye.transform.position+facing*new Vector3(0,-.28f,.85f)*rig.localScale.x;
  if(!dockPosed){view.transform.SetPositionAndRotation(position,facing);dockPosed=true;dockEyeAt=eye.transform.position;}else{view.transform.position+=eye.transform.position-dockEyeAt;dockEyeAt=eye.transform.position;}if(!Open&&!DockHovered&&!dockPressedLast){float turn=Quaternion.Angle(view.transform.rotation,facing);followDwell=turn>8?followDwell+Mathf.Min(dt,.05f):0;if(followDwell>.2f||!xr){float t=1-Mathf.Exp(-Mathf.Min(dt,.05f)*7);view.transform.rotation=Quaternion.Slerp(view.transform.rotation,facing,t);}view.transform.position=Vector3.Lerp(view.transform.position,position,1-Mathf.Exp(-Mathf.Min(dt,.05f)*10));}view.transform.localScale=Vector3.one*.00065f*rig.localScale.x;
 }
 bool DockHit(Ray ray,out Collider result){Collider chosen=null;float nearest=8*rig.localScale.x;Test(dockRail);Test(toolRail);foreach(var c in CategoryButtons)Test(c);foreach(var c in choices)Test(c);foreach(var c in UtilityButtons)Test(c);result=chosen;return chosen!=null;
  void Test(Collider c){if(c!=null&&c.enabled&&c.gameObject.activeInHierarchy&&c.Raycast(ray,out var hit,nearest)){nearest=hit.distance;chosen=c;}}
 }
 bool ProcessDock(Ray ray,bool pressed,float dt,bool xr){view.SetActive(true);PoseDock(dt,xr);var uiRay=!xr&&UseDesktopCursor&&Mouse.current!=null?eye.ScreenPointToRay(Mouse.current.position.ReadValue()):ray;Physics.SyncTransforms();bool hit=DockHit(uiRay,out var target);DockHovered=hit;if(hit&&target.Raycast(uiRay,out var dockContact,8*rig.localScale.x))DockPointerPoint=dockContact.point;bool edge=pressed&&!dockPressedLast&&!releaseGate;dockPressedLast=pressed;dockIdle=hit||Open||pressed?0:dockIdle+Mathf.Min(dt,.1f);dockFade.alpha=Mathf.MoveTowards(dockFade.alpha,hit||Open||dockIdle<2?1:.28f,Mathf.Min(dt,.1f)*4);
  for(int i=0;i<5;i++){bool active=Open?i==(int)ActiveCategory:Selected.HasValue&&i==(int)CategoryFor(Selected.Value);categoryImages[i].color=target==CategoryButtons[i]||active?new Color(1.4f,1.2f,.75f):Color.white;}
  for(int i=0;i<ToolCount;i++){bool hover=target==choices[i];choices[i].GetComponent<UnityEngine.UI.Image>().color=hover?new Color(1.4f,1.2f,.75f):Color.white;toolLabels[i].gameObject.SetActive(hover||Selected==ToolKinds[i]);}
  dockTooltip.gameObject.SetActive(hit||Open);dockTooltip.text=hit?target.name:ActiveCategory.ToString();energy.text=miracles.UnlimitedEnergy?"Energy unlimited":$"Energy {Season.Hybrid.energy:0}";energyFill.rectTransform.sizeDelta=new Vector2(68*(miracles.UnlimitedEnergy?1:Mathf.Clamp01(Season.Hybrid.energy/Mathf.Max(1,miracles.tuning.maximum))),3);
  if(hit){if(pressed)releaseGate=true;if(Selected.HasValue){Brush.Stop();CancelSculpt();SeedVisibility(false);preview.SetActive(false);hint.gameObject.SetActive(false);}if(edge){int category=Array.IndexOf(CategoryButtons,target),tool=Array.IndexOf(choices,target);if(category>=0){if(Open&&ActiveCategory==(GodToolCategory)category){Open=false;RefreshDockRows();releaseGate=true;}else OpenCategory((GodToolCategory)category);}else if(tool>=0&&tool<ToolCount)Select(ToolKinds[tool]);else if(target==UtilityButtons[0])Cancel();else if(target==choices[ToolCount]){ClearSign();releaseGate=true;}else if(target==UtilityButtons[1]||target==UtilityButtons[2]){Cancel();HideDock();if(target==UtilityButtons[1])showBook?.Invoke();else if(target==UtilityButtons[2])showMenu?.Invoke();}}return true;}
  if(Open){if(edge){Open=false;RefreshDockRows();releaseGate=true;}return true;}if(Selected==SpiritualTool.PlantSeeds)SeedVisibility(true);return false;
 }
 void DisposeDock(){if(dockDisk!=null)Destroy(dockDisk);if(dockInk!=null)Destroy(dockInk);}
}
